/// <reference types="svelte" />
/**
 * Store: resources — see CARTOGRAPHY.md
 * Consumers: Header → ResourceBar
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { ResourceSnapshot } from '../bus/snapshots.js';
import { shallowEqualShards } from './storeUtils.js';
import { registerResourcesSnapshotGetter } from './resourcesSnapshotGetter.js';
import { deferIfMobileScrolling } from '../lib/mobileScrollGate.ts';

class ResourceStore {
  pokedollars = $state(0);
  essenceDust = $state(0);
  shinyDust = $state(0);
  shadowDust = $state(0);
  specialIncubatorsUnlocked = $state(false);
  shinyContributionLevel = $state(0);
  shadowContributionLevel = $state(0);
  shinyDustYieldLevel = $state(0);
  shadowDustYieldLevel = $state(0);
  talentRerolls = $state(0);
  talentChoices = $state(0);
  questTokens = $state(0);
  combatTickets = $state(0);
  triumphMarks = $state(0);
  shards: Record<string, number> = $state({});
  activeVitamins: ResourceSnapshot['activeVitamins'] = $state({
    hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0, all: 0,
  });
}

export const resources = new ResourceStore();

function currentResourcesSnapshot(): ResourceSnapshot {
  return {
    pokedollars: resources.pokedollars,
    essenceDust: resources.essenceDust,
    shinyDust: resources.shinyDust,
    shadowDust: resources.shadowDust,
    specialIncubatorsUnlocked: resources.specialIncubatorsUnlocked,
    shinyContributionLevel: resources.shinyContributionLevel,
    shadowContributionLevel: resources.shadowContributionLevel,
    shinyDustYieldLevel: resources.shinyDustYieldLevel,
    shadowDustYieldLevel: resources.shadowDustYieldLevel,
    talentRerolls: resources.talentRerolls,
    talentChoices: resources.talentChoices,
    questTokens: resources.questTokens,
    combatTickets: resources.combatTickets,
    triumphMarks: resources.triumphMarks,
    shards: { ...resources.shards },
    activeVitamins: { ...resources.activeVitamins },
  };
}

registerResourcesSnapshotGetter(currentResourcesSnapshot);

facade.subscribe(Evt.RESOURCES_CHANGED, (evt) => {
  if (!('resources' in evt)) return;
  const specialIncubatorsUnlocked = evt.resources.specialIncubatorsUnlocked === true;
  if (specialIncubatorsUnlocked !== resources.specialIncubatorsUnlocked) resources.specialIncubatorsUnlocked = specialIncubatorsUnlocked;
  deferIfMobileScrolling('resources', () => {
  const r = evt.resources;
  if (r.pokedollars !== resources.pokedollars) resources.pokedollars = r.pokedollars;
  if (r.essenceDust !== resources.essenceDust) resources.essenceDust = r.essenceDust;
  if (r.shinyDust !== resources.shinyDust) resources.shinyDust = r.shinyDust;
  if (r.shadowDust !== resources.shadowDust) resources.shadowDust = r.shadowDust;
  const shinyLevel = r.shinyContributionLevel ?? 0;
  const shadowLevel = r.shadowContributionLevel ?? 0;
  if (shinyLevel !== resources.shinyContributionLevel) resources.shinyContributionLevel = shinyLevel;
  if (shadowLevel !== resources.shadowContributionLevel) resources.shadowContributionLevel = shadowLevel;
  const shinyDustYieldLevel = r.shinyDustYieldLevel ?? 0;
  const shadowDustYieldLevel = r.shadowDustYieldLevel ?? 0;
  if (shinyDustYieldLevel !== resources.shinyDustYieldLevel) resources.shinyDustYieldLevel = shinyDustYieldLevel;
  if (shadowDustYieldLevel !== resources.shadowDustYieldLevel) resources.shadowDustYieldLevel = shadowDustYieldLevel;
  if (r.talentRerolls !== resources.talentRerolls) resources.talentRerolls = r.talentRerolls;
  if (r.talentChoices !== resources.talentChoices) resources.talentChoices = r.talentChoices;
  if (r.questTokens !== resources.questTokens) resources.questTokens = r.questTokens;
  if (r.combatTickets !== resources.combatTickets) resources.combatTickets = r.combatTickets;
  if (r.triumphMarks !== resources.triumphMarks) resources.triumphMarks = r.triumphMarks;
  if (!shallowEqualShards(r.shards, resources.shards)) resources.shards = r.shards;
  const va = r.activeVitamins;
  if (va) {
    if (va.hp !== resources.activeVitamins.hp) resources.activeVitamins.hp = va.hp;
    if (va.attack !== resources.activeVitamins.attack) resources.activeVitamins.attack = va.attack;
    if (va.spattack !== resources.activeVitamins.spattack) resources.activeVitamins.spattack = va.spattack;
    if (va.defense !== resources.activeVitamins.defense) resources.activeVitamins.defense = va.defense;
    if (va.spdefense !== resources.activeVitamins.spdefense) resources.activeVitamins.spdefense = va.spdefense;
    if (va.speed !== resources.activeVitamins.speed) resources.activeVitamins.speed = va.speed;
    if (va.all !== resources.activeVitamins.all) resources.activeVitamins.all = va.all;
  }
  });
});
